CREATE TABLE layouts (
        id           TEXT PRIMARY KEY NOT NULL,
        workspace_id TEXT NOT NULL,
        title        TEXT NOT NULL,
        description  TEXT NOT NULL DEFAULT '',
        preview_hint TEXT NOT NULL DEFAULT '',
        builtin      INTEGER NOT NULL DEFAULT 0,
        created_at   INTEGER NOT NULL
    );
CREATE TABLE layout_versions (
        layout_id  TEXT NOT NULL,
        version    INTEGER NOT NULL,
        hash       TEXT NOT NULL,
        source     TEXT NOT NULL,
        prompt     TEXT,
        provider   TEXT,
        patch_json TEXT,
        created_at INTEGER NOT NULL,
        PRIMARY KEY (layout_id, version)
    ) WITHOUT ROWID;
CREATE TABLE workspace_revisions (
        workspace_id   TEXT NOT NULL,
        revision       INTEGER NOT NULL,
        layout_id      TEXT NOT NULL,
        layout_version INTEGER NOT NULL,
        reason         TEXT NOT NULL,
        created_at     INTEGER NOT NULL,
        PRIMARY KEY (workspace_id, revision)
    ) WITHOUT ROWID;
CREATE TABLE app_versions (
        app_id     TEXT NOT NULL,
        version    INTEGER NOT NULL,
        hash       TEXT NOT NULL REFERENCES layout_blobs (hash),
        source     TEXT NOT NULL,
        note       TEXT,
        file_key   TEXT UNIQUE,
        created_at INTEGER NOT NULL, file_hash TEXT, features TEXT NOT NULL DEFAULT '', author TEXT, meta_json TEXT,
        PRIMARY KEY (app_id, version)
    ) WITHOUT ROWID;
