INSERT INTO adapter_migrations VALUES('recipes',2);
INSERT INTO adapter_migrations VALUES('events',1);
INSERT INTO adapter_migrations VALUES('collections',12);
INSERT INTO adapter_migrations VALUES('agents',4);
CREATE TABLE session_sign_ins (
         token_hash TEXT NOT NULL,
         provider   TEXT NOT NULL,
         created_at INTEGER NOT NULL,
         PRIMARY KEY (token_hash, provider)
     );
CREATE TABLE pod_settings (
         key   TEXT PRIMARY KEY NOT NULL,
         value TEXT NOT NULL
     );
INSERT INTO pod_settings VALUES('apps.hidden','["c-o4pmrfxsm3"]');
INSERT INTO pod_settings VALUES('updates.dismissed','{"c-r7jeifhpzm":2}');
CREATE TABLE uploads (
         id           TEXT PRIMARY KEY NOT NULL,
         token_hash   TEXT NOT NULL,
         idem_key     TEXT NOT NULL,
         content_type TEXT NOT NULL,
         size         INTEGER NOT NULL,
         sha256       TEXT NOT NULL,
         data         BLOB NOT NULL,
         owner        TEXT,
         created_at   INTEGER NOT NULL,
         released_at  INTEGER,
         UNIQUE (token_hash, idem_key)
     );
CREATE TABLE notifications (
         id          INTEGER PRIMARY KEY AUTOINCREMENT,
         layout      TEXT NOT NULL,
         channel     TEXT NOT NULL,
         dedupe_key  TEXT NOT NULL,
         title       TEXT NOT NULL,
         body        TEXT NOT NULL DEFAULT '',
         image_url   TEXT,
         target_uri  TEXT,
         group_key   TEXT,
         created_at  INTEGER NOT NULL,
         inserted_at INTEGER NOT NULL,
         read_at     INTEGER,
         UNIQUE (layout, dedupe_key)
     );
CREATE TABLE notification_polls (
         adapter     TEXT PRIMARY KEY NOT NULL,
         next_at     INTEGER NOT NULL,
         failures    INTEGER NOT NULL DEFAULT 0,
         last_error  TEXT,
         stopped_for TEXT
     );
CREATE TABLE devices (
         id            TEXT PRIMARY KEY NOT NULL,
         token_hash    TEXT NOT NULL,
         platform      TEXT NOT NULL,
         name          TEXT NOT NULL DEFAULT '',
         created_at    INTEGER NOT NULL,
         last_seen     INTEGER NOT NULL,
         push_endpoint TEXT,
         push_p256dh   TEXT,
         push_auth     TEXT,
         push_failures INTEGER NOT NULL DEFAULT 0
     );
CREATE TABLE device_channel_prefs (
         device_id TEXT NOT NULL,
         layout    TEXT NOT NULL,
         channel   TEXT NOT NULL,
         enabled   INTEGER NOT NULL,
         PRIMARY KEY (device_id, layout, channel)
     );
CREATE TABLE custom_apps (
         id         TEXT PRIMARY KEY NOT NULL,
         title      TEXT NOT NULL,
         icon       TEXT NOT NULL,
         feeds_json TEXT NOT NULL,
         created_at INTEGER NOT NULL,
         updated_at INTEGER NOT NULL,
         deleted_at INTEGER
     );
