CREATE TABLE components (
            name       TEXT NOT NULL,
            version    INTEGER NOT NULL,
            json       TEXT NOT NULL,
            note       TEXT,
            author     TEXT NOT NULL,
            file_hash  TEXT,
            meta_json  TEXT,
            created_at INTEGER NOT NULL,
            PRIMARY KEY (name, version)
        ) WITHOUT ROWID;
INSERT INTO components VALUES('core:author_header',1,'{"doc":"Who posted: a round avatar beside the name and, below it, the handle.","examples":[{"args":{"avatar":"$item.author_avatar_url","handle":"$item.author_handle","name":"$item.author_name"},"note":"a post''s author"}],"params":[{"doc":"The avatar image URL.","name":"avatar","required":true,"type":"binding"},{"doc":"The name.","name":"name","required":true,"type":"text"},{"default":"","doc":"The handle (left out when empty).","name":"handle","type":"text"},{"default":36,"doc":"Avatar size.","name":"size","type":"number"},{"default":10,"doc":"Space between avatar and name.","name":"spacing","type":"number"},{"default":12,"doc":"Side padding.","name":"padding_h","type":"number"},{"default":10,"doc":"Top and bottom padding.","name":"padding_v","type":"number"}],"template":{"children":[{"shape":"Circle","size_dp":"$arg.size","type":"core://Image","url":"$arg.avatar"},{"children":[{"style":"Label","type":"core://Text","value_expr":"$arg.name"},{"arg":"handle","then":{"style":"Secondary","type":"core://Text","value_expr":"$arg.handle"},"type":"core://IfArg"}],"type":"core://Column"}],"padding_h_dp":"$arg.padding_h","padding_v_dp":"$arg.padding_v","spacing_dp":"$arg.spacing","type":"core://Row"}}','First version','server','a6c7b2bdb33978d80d3296b0fe4eadf7d36a555017348f25d67a55356e3f51ce',NULL,1794840857);
INSERT INTO components VALUES('core:back_button',1,'{"doc":"Back (the arrow), shown only where the page can go back (local://nav#can_go_back).","examples":[{"args":{},"note":"in a header row"}],"params":[],"template":{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#can_go_back}"}}','First version','server','0f0fa1bf7307790097162780bb3dee64f8a5b69d5fbe8b633c4d5ad639b4a544',NULL,1794840857);
INSERT INTO components VALUES('core:card',1,'{"children":true,"doc":"A bordered, rounded card holding its children in a column (events, sites, alerts). Wrap it in core://Tappable to open something.","examples":[{"args":{"spacing":6},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.title"},{"style":"Secondary","type":"core://Text","value_expr":"$item.venue"}],"note":"an event"}],"params":[{"default":0,"doc":"Space between the children.","name":"spacing","type":"number"},{"default":"#E4E4EA","doc":"Border colour (#RRGGBB or a binding such as ${local://theme#card_border}).","name":"border","type":"text"}],"template":{"border_color":"$arg.border","content":{"children":[{"type":"core://Children"}],"spacing_dp":"$arg.spacing","type":"core://Column"},"corner_dp":14,"padding_h_dp":14,"padding_v_dp":12,"type":"core://Box"}}','First version','server','f4f0c2a55d466cf5b48af74f9c63542904f9af539cf2118998725f211f9ddfe6',NULL,1794840857);
INSERT INTO components VALUES('core:card',2,'{"children":true,"doc":"A bordered, rounded card holding its children in a column (events, sites, alerts). Wrap it in core://Tappable to open something.","examples":[{"args":{"spacing":6},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.title"},{"style":"Secondary","type":"core://Text","value_expr":"$item.venue"}],"note":"an event"}],"params":[{"default":0,"doc":"Space between the children.","name":"spacing","type":"number"},{"default":"${local://theme#card_border}","doc":"Border colour (#RRGGBB or a binding such as ${local://theme#card_border}).","name":"border","type":"text"},{"default":"${local://theme#card}","doc":"Fill colour (#RRGGBB or a binding such as ${local://theme#card}).","name":"background","type":"text"}],"template":{"background":"$arg.background","border_color":"$arg.border","content":{"children":[{"type":"core://Children"}],"spacing_dp":"$arg.spacing","type":"core://Column"},"corner_dp":14,"padding_h_dp":14,"padding_v_dp":12,"type":"core://Box"}}','Theme colours: the card token''s fill and card_border, so cards follow dark mode','server','903c8b23c4f51ffe5d88a893754fcfdad03e7d0248d47b7e8af82440d964f526',NULL,1794840857);
INSERT INTO components VALUES('core:card',3,'{"children":true,"doc":"A bordered, rounded card holding its children in a column (events, sites, alerts). Wrap it in core://Tappable to open something.","examples":[{"args":{"spacing":6},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.title"},{"style":"Secondary","type":"core://Text","value_expr":"$item.venue"}],"note":"an event"},{"args":{"corner":12,"spacing":4},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.store"},{"style":"Secondary","type":"core://Text","value_expr":"$item.why"}],"note":"an option to pick, with tighter corners"},{"args":{"corner":12,"spacing":6},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.title"},{"style":"Secondary","type":"core://Text","value_expr":"$item.body"}],"note":"a notification"}],"params":[{"default":0,"doc":"Space between the children.","name":"spacing","type":"number"},{"default":"${local://theme#card_border}","doc":"Border colour (#RRGGBB or a binding such as ${local://theme#card_border}).","name":"border","type":"text"},{"default":"${local://theme#card}","doc":"Fill colour (#RRGGBB or a binding such as ${local://theme#card}).","name":"background","type":"text"},{"default":14,"doc":"Corner radius.","name":"corner","type":"number"}],"template":{"background":"$arg.background","border_color":"$arg.border","content":{"children":[{"type":"core://Children"}],"spacing_dp":"$arg.spacing","type":"core://Column"},"corner_dp":"$arg.corner","padding_h_dp":14,"padding_v_dp":12,"type":"core://Box"}}','A corner parameter (default 14, as before), so cards with tighter corners are cards too','server','961e5e82be6f395feb34fe279d472b69a63de87989ca0032dd395a74f8b3776d',NULL,1794840857);
INSERT INTO components VALUES('core:chevron_card',1,'{"children":true,"doc":"A rounded card that opens something: its children on one centred row, then a › at the end (what''s coming up, a priority, a step of a plan). Wrap it in core://Tappable.","examples":[{"args":{"background":"${local://theme#accent}","color":"${local://theme#card}"},"children":[{"children":[{"style":"Title","type":"core://Text","value_expr":"Book club · Thursday"},{"style":"Secondary","type":"core://Text","value_expr":"3 chapters to go"}],"spacing_dp":2,"type":"core://Column"}],"note":"what''s coming up, filled"},{"args":{"border":"${local://theme#card_border}"},"children":[{"align":"Center","content":{"style":"Headline","type":"core://Text","value_expr":"1"},"type":"core://Box","width_dp":28},{"children":[{"style":"Title","type":"core://Text","value_expr":"Pick a route"},{"style":"Secondary","type":"core://Text","value_expr":"$item.routes_left routes to look at"}],"spacing_dp":2,"type":"core://Column"}],"note":"a numbered step of a plan, bordered"}],"params":[{"default":"${local://theme#card}","doc":"Fill colour (#RRGGBB or a binding such as ${local://theme#accent_surface}).","name":"background","type":"text"},{"default":"","doc":"Colour of the text and icons inside (#RRGGBB or a binding); empty keeps their own.","name":"color","type":"text"},{"default":"","doc":"Border colour (#RRGGBB or a binding such as ${local://theme#card_border}); empty for none.","name":"border","type":"text"}],"template":{"background":"$arg.background","border_color":{"arg":"border","then":"$arg.border","type":"core://IfArg"},"content":{"align":"Center","children":[{"type":"core://Children"},{"type":"core://Spacer"},{"style":"Headline","type":"core://Text","value_expr":"›"}],"spacing_dp":12,"type":"core://Row"},"content_color":{"arg":"color","then":"$arg.color","type":"core://IfArg"},"corner_dp":14,"padding_h_dp":16,"padding_v_dp":14,"type":"core://Box"}}','First version: the rounded card with a row of content and a › at its end that launcher and step layouts repeat','server','ce911ff675c20dfc0395dc6bc123aa0e2d6759c48dee0d47caff002299a8e6ac',NULL,1794840857);
INSERT INTO components VALUES('core:divided_item',1,'{"children":true,"doc":"A list item set off from the next: its children in a column with a divider under them (a log entry, a task, a setting).","examples":[{"args":{},"children":[{"children":[{"style":"Caption","type":"core://Text","value_expr":"$item.date"},{"style":"Body","type":"core://Text","value_expr":"$item.title"}],"padding_v_dp":12,"spacing_dp":12,"type":"core://Row"}],"note":"a timeline entry, the divider edge to edge"},{"args":{"inset":16},"children":[{"children":[{"style":"Label","type":"core://Text","value_expr":"$item.title"},{"type":"core://Spacer"},{"style":"Secondary","type":"core://Text","value_expr":"$item.status_text"}],"padding_h_dp":16,"padding_v_dp":10,"spacing_dp":12,"type":"core://Row"}],"note":"a status row, the divider inset to the row''s padding"}],"params":[{"default":0,"doc":"Side padding of the divider; 0 runs it edge to edge.","name":"inset","type":"number"}],"template":{"children":[{"type":"core://Children"},{"arg":"inset","else":{"type":"core://Divider"},"then":{"children":[{"type":"core://Divider"}],"padding_h_dp":"$arg.inset","type":"core://Column"},"type":"core://IfArg"}],"type":"core://Column"}}','First version: the list item with a divider under it that log, task and settings layouts repeat','server','62c3d6298c0e371e8889e1a24a50eb6d7426d719b1f0b316b536070d106ef815',NULL,1794840857);
INSERT INTO components VALUES('core:dot',1,'{"doc":"A small coloured dot (unread, online).","examples":[{"args":{"color":"#1E66D0"},"note":"an unread dot"},{"args":{"color":"${local://connection#color}","corner":5,"size":10},"note":"the connection dot"}],"params":[{"doc":"Its colour (#RRGGBB or a binding).","name":"color","required":true,"type":"text"},{"default":8,"doc":"Its diameter.","name":"size","type":"number"},{"default":4,"doc":"Corner radius: half the size for a circle.","name":"corner","type":"number"}],"template":{"background":"$arg.color","content":{"type":"core://Spacer"},"corner_dp":"$arg.corner","height_dp":"$arg.size","type":"core://Box","width_dp":"$arg.size"}}','First version','server','8b84e63fb96fd310631e069d40db3bb5b468c3935ac9889084f781d118969b53',NULL,1794840857);
INSERT INTO components VALUES('core:filled_card',1,'{"children":true,"doc":"A filled, rounded card holding its children in a column, its text in one colour: an item''s heading on its screen, a status at a glance. The filled counterpart of core:card. Wrap it in core://Tappable to open something.","examples":[{"args":{"background":"${local://theme#accent_surface}","color":"${local://theme#accent}","spacing":6},"children":[{"style":"Label","type":"core://Text","value_expr":"$item.when"},{"style":"Headline","type":"core://Text","value_expr":"$item.title"}],"note":"an item''s heading on its own screen"},{"args":{"background":"#1E8E3E","color":"#FFFFFF","padding_h":20,"padding_v":18,"spacing":4},"children":[{"style":"Display","type":"core://Text","value_expr":"All good"},{"style":"Body","type":"core://Text","value_expr":"Up for 3 days"}],"note":"a status at a glance"}],"params":[{"doc":"Fill colour (#RRGGBB or a binding such as ${local://theme#accent_surface}).","name":"background","required":true,"type":"text"},{"doc":"Colour of the text and icons inside (#RRGGBB or a binding such as ${local://theme#accent}).","name":"color","required":true,"type":"text"},{"default":0,"doc":"Space between the children.","name":"spacing","type":"number"},{"default":16,"doc":"Side padding.","name":"padding_h","type":"number"},{"default":16,"doc":"Top and bottom padding.","name":"padding_v","type":"number"}],"template":{"background":"$arg.background","content":{"children":[{"type":"core://Children"}],"spacing_dp":"$arg.spacing","type":"core://Column"},"content_color":"$arg.color","corner_dp":16,"padding_h_dp":"$arg.padding_h","padding_v_dp":"$arg.padding_v","type":"core://Box"}}','First version','server','8fbb8eadf1dd165fa2b260df17bbb3760269bb57350687e2b94f4449d9708074',NULL,1794840857);
INSERT INTO components VALUES('core:footer_bar',1,'{"children":true,"doc":"A bar along the bottom of a page: a divider, then its children on one centred row (a count or a status, a Spacer, a button). Put it after the page''s scrolling content.","examples":[{"args":{},"children":[{"count":{"query_key":"collection:chores","where":[{"equals":"true","field":"done"}],"zero_text":"Tap a chore when it''s done"},"style":"Secondary","type":"core://Text","value_expr":"$count done"},{"type":"core://Spacer"},{"label":"Clear done","on_click":{"endpoint":"/v1/collections/chores/actions/clear_done","entity_uri":"collections://chores/settings","field":"busy","intent":"action.mutation.optimistic","payload":{"client_id":"clear-$nonce"},"value_expr":"true"},"type":"core://Button"}],"note":"a list''s count and a button that clears what is done"},{"args":{"padding_v":6},"children":[{"style":"Caption","type":"core://Text","value_expr":"Drafts are kept on this device"},{"type":"core://Spacer"},{"label":"Send","on_click":{"intent":"action.navigation.back"},"type":"core://Button"}],"note":"a compose page''s status and its send button, a tighter bar"}],"params":[{"default":16,"doc":"Side padding.","name":"padding_h","type":"number"},{"default":10,"doc":"Top and bottom padding.","name":"padding_v","type":"number"}],"template":{"children":[{"type":"core://Divider"},{"align":"Center","children":[{"type":"core://Children"}],"padding_h_dp":"$arg.padding_h","padding_v_dp":"$arg.padding_v","spacing_dp":8,"type":"core://Row"}],"type":"core://Fragment"}}','First version: the bar under a page''s list (a count and a button, under a divider) that list layouts repeat','server','0702f1dccd7feb3589e8c7cff45f3f1e7b538341e147684974287ca21a593b52',NULL,1794840857);
INSERT INTO components VALUES('core:header_bar',1,'{"children":true,"doc":"A bar with a title on the left and actions (icon buttons) on the right.","examples":[{"args":{"title":"Home"},"children":[{"content_description":"Notifications","icon":"notifications","on_click":{"intent":"action.navigation.open","layout":"inbox","presentation":"Sheet"},"type":"core://IconButton"},{"content_description":"Settings","icon":"settings","on_click":{"intent":"action.navigation.open","layout":"settings","presentation":"Panel"},"type":"core://IconButton"}],"note":"home''s header: the title, the bell and the gear on one line"}],"params":[{"doc":"The title.","name":"title","required":true,"type":"text"},{"default":"Title","doc":"A core://Text style.","name":"style","type":"text"},{"default":12,"doc":"Side padding.","name":"padding_h","type":"number"},{"default":4,"doc":"Top and bottom padding.","name":"padding_v","type":"number"}],"template":{"children":[{"style":"$arg.style","type":"core://Text","value_expr":"$arg.title"},{"type":"core://Spacer"},{"type":"core://Children"}],"padding_h_dp":"$arg.padding_h","padding_v_dp":"$arg.padding_v","type":"core://Row"}}','First version','server','439d290e09936b7f357724e819ffde4efd6fb481bc2c021ce142e907e0e7e3e8',NULL,1794840857);
INSERT INTO components VALUES('core:labeled_text',1,'{"doc":"A small label above a text, shown only while the text is set: one field of an item on its screen (Description, About, Notes).","examples":[{"args":{"label":"About","text":"$item.description"},"note":"an event''s description on its screen"},{"args":{"label":"Description","padding_h":4,"text":"$item.notes"},"note":"a task''s notes, inset to line up with its card"}],"params":[{"doc":"The label (About).","name":"label","required":true,"type":"text"},{"doc":"The text (a binding such as $item.description); the block is left out while it is empty.","name":"text","required":true,"type":"binding"},{"default":0,"doc":"Side padding.","name":"padding_h","type":"number"}],"template":{"content":{"arg":"padding_h","else":{"children":[{"style":"Label","type":"core://Text","value_expr":"$arg.label"},{"style":"Body","type":"core://Text","value_expr":"$arg.text"}],"spacing_dp":6,"type":"core://Column"},"then":{"children":[{"style":"Label","type":"core://Text","value_expr":"$arg.label"},{"style":"Body","type":"core://Text","value_expr":"$arg.text"}],"padding_h_dp":"$arg.padding_h","spacing_dp":6,"type":"core://Column"},"type":"core://IfArg"},"type":"core://Conditional","value":"$arg.text"}}','First version: the label over a text (an item''s Description, About) that detail screens repeat','server','b5bbd136ff17422e2a54384bff4bee226d4c99e5bfa5466b78d87d02b28b278e',NULL,1794840857);
INSERT INTO components VALUES('core:link_button',1,'{"doc":"A button that opens a web link, shown only while the link is set.","examples":[{"args":{"label":"Get tickets","url":"$item.tickets_url"},"note":"tickets when the event has them"}],"params":[{"doc":"The button''s text.","name":"label","required":true,"type":"text"},{"doc":"The link (a binding such as $item.url).","name":"url","required":true,"type":"binding"}],"template":{"content":{"label":"$arg.label","on_click":{"intent":"action.link.open","url":"$arg.url"},"type":"core://Button"},"type":"core://Conditional","value":"$arg.url"}}','First version','server','9375195ce2f440b1c897c0eefd2d611aecf36446cceff8061626e43671e46ee3',NULL,1794840857);
INSERT INTO components VALUES('core:list_row',1,'{"doc":"A row of a list: a title on the left and a quiet trailing text on the right (a value, a version, a count).","examples":[{"args":{"title":"$item.title","trailing":"$item.version"},"note":"a layout and its version"}],"params":[{"doc":"The main text.","name":"title","required":true,"type":"text"},{"default":"","doc":"The text at the end.","name":"trailing","type":"text"},{"default":10,"doc":"Space above and below.","name":"padding_v","type":"number"}],"template":{"children":[{"style":"Body","type":"core://Text","value_expr":"$arg.title"},{"type":"core://Spacer"},{"style":"Secondary","type":"core://Text","value_expr":"$arg.trailing"}],"padding_h_dp":16,"padding_v_dp":"$arg.padding_v","spacing_dp":8,"type":"core://Row"}}','First version','server','903b1115345d83d1275ed874f129a6b380cfbdb7d6d3af3da73b92d75001dbd1',NULL,1794840857);
INSERT INTO components VALUES('core:message_page',1,'{"children":true,"doc":"A whole page with a message in the middle and actions under it (a welcome, an error with Try again).","examples":[{"args":{"body":"Ask your agent to build anything","title":"The Construct"},"children":[{"content_description":"Settings","icon":"settings","on_click":{"intent":"action.navigation.open","layout":"settings","presentation":"Panel"},"type":"core://IconButton"}],"note":"a blank home"}],"params":[{"default":"","doc":"A large title (left out when empty).","name":"title","type":"text"},{"doc":"The message.","name":"body","required":true,"type":"text"},{"default":"#F7F5F0","doc":"Page colour.","name":"background","type":"text"}],"template":{"align":"Center","background":"$arg.background","content":{"align":"Center","children":[{"arg":"title","then":{"style":"Display","type":"core://Text","value_expr":"$arg.title"},"type":"core://IfArg"},{"style":"Secondary","type":"core://Text","value_expr":"$arg.body"},{"align":"Center","children":[{"type":"core://Children"}],"spacing_dp":8,"type":"core://Row"}],"spacing_dp":8,"type":"core://Column"},"fill":true,"padding_h_dp":24,"type":"core://Box"}}','First version','server','250ac9b8003549a868a6f71ef9312b50133f7f4baf8534309beb407abac0f382',NULL,1794840857);
INSERT INTO components VALUES('core:message_page',2,'{"children":true,"doc":"A whole page with a message in the middle and actions under it (a welcome, an error with Try again).","examples":[{"args":{"body":"Ask your agent to build anything","title":"The Construct"},"children":[{"content_description":"Settings","icon":"settings","on_click":{"intent":"action.navigation.open","layout":"settings","presentation":"Panel"},"type":"core://IconButton"}],"note":"a blank home"}],"params":[{"default":"","doc":"A large title (left out when empty).","name":"title","type":"text"},{"doc":"The message.","name":"body","required":true,"type":"text"},{"default":"${local://theme#page}","doc":"Page colour.","name":"background","type":"text"}],"template":{"align":"Center","background":"$arg.background","content":{"align":"Center","children":[{"arg":"title","then":{"style":"Display","type":"core://Text","value_expr":"$arg.title"},"type":"core://IfArg"},{"style":"Secondary","type":"core://Text","value_expr":"$arg.body"},{"align":"Center","children":[{"type":"core://Children"}],"spacing_dp":8,"type":"core://Row"}],"spacing_dp":8,"type":"core://Column"},"fill":true,"padding_h_dp":24,"type":"core://Box"}}','Theme colours: the page token, so it follows dark mode','server','64966a24787927c3519b4c90958fef2f6a941450ea06db2848cba49ed7bb26c1',NULL,1794840857);
INSERT INTO components VALUES('core:page_header',1,'{"children":true,"doc":"A page''s header on one line: Back (while the page can go back), the title, and actions (icon buttons) on the right. The top of a layout whose root is a core://Page, which gets no chrome from the app.","examples":[{"args":{"title":"Reading list"},"note":"a pushed list page: Back and the title, no actions"},{"args":{"title":"Packing"},"children":[{"content_description":"Add an item","icon":"add","on_click":{"intent":"action.navigation.open","layout":"c-example","presentation":"Sheet"},"type":"core://IconButton"}],"note":"a checklist page with an add button on the right"},{"args":{"style":"Headline","title":"${collections://trips/$route.id#name}"},"note":"an item''s page titled from its data, in the headline style"}],"params":[{"doc":"The title (bindings allowed).","name":"title","required":true,"type":"text"},{"default":"Title","doc":"A core://Text style.","name":"style","type":"text"},{"default":12,"doc":"Side padding.","name":"padding_h","type":"number"},{"default":4,"doc":"Top and bottom padding.","name":"padding_v","type":"number"}],"template":{"align":"Center","children":[{"component":"core:back_button","type":"core://Use"},{"style":"$arg.style","type":"core://Text","value_expr":"$arg.title"},{"type":"core://Spacer"},{"type":"core://Children"}],"padding_h_dp":"$arg.padding_h","padding_v_dp":"$arg.padding_v","spacing_dp":4,"type":"core://Row"}}','First version: the header row pages with their own chrome repeat (Back, the title, actions on the right)','server','e5553365a65dc332ca2d059f75083491c8116b4591a5ee3d2a98435ea97a4f13',NULL,1794840857);
INSERT INTO components VALUES('core:pill',1,'{"doc":"A small tinted tag with text (a date, a status).","examples":[{"args":{"text":"$item.start_text"},"note":"an event''s date"}],"params":[{"doc":"The text.","name":"text","required":true,"type":"text"},{"default":"#EFE9FA","doc":"Fill colour.","name":"background","type":"text"},{"default":"#4A2C82","doc":"Text colour.","name":"color","type":"text"},{"default":"Caption","doc":"A core://Text style.","name":"style","type":"text"}],"template":{"background":"$arg.background","content":{"style":"$arg.style","type":"core://Text","value_expr":"$arg.text"},"content_color":"$arg.color","corner_dp":8,"padding_h_dp":8,"padding_v_dp":3,"type":"core://Box"}}','First version','server','0a0a18c83072dd4caa9460f23babd11dc760872570f2f5f6eefcb4efceaf231a',NULL,1794840857);
INSERT INTO components VALUES('core:pill',2,'{"doc":"A small tinted tag with text (a date, a status).","examples":[{"args":{"text":"$item.start_text"},"note":"an event''s date"}],"params":[{"doc":"The text.","name":"text","required":true,"type":"text"},{"default":"${local://theme#accent_surface}","doc":"Fill colour.","name":"background","type":"text"},{"default":"${local://theme#accent}","doc":"Text colour.","name":"color","type":"text"},{"default":"Caption","doc":"A core://Text style.","name":"style","type":"text"}],"template":{"background":"$arg.background","content":{"style":"$arg.style","type":"core://Text","value_expr":"$arg.text"},"content_color":"$arg.color","corner_dp":8,"padding_h_dp":8,"padding_v_dp":3,"type":"core://Box"}}','Theme colours: accent_surface and accent, so pills follow dark mode','server','b4c6c3825f09e3dd77874e76f95dffaf0b87bbde58a7f4c99a7f452a61ff1c03',NULL,1794840857);
INSERT INTO components VALUES('core:pill',3,'{"doc":"A small tinted tag with text (a date, a status, a count).","examples":[{"args":{"text":"$item.start_text"},"note":"an event''s date"},{"args":{"background":"${local://theme#error_surface}","color":"${local://theme#error}","corner":6,"text":"$item.status"},"note":"a task''s status, with tighter corners"},{"args":{"background":"${local://theme#unread}","color":"${local://theme#card}","corner":6,"text":"3 unread"},"note":"a count on a list row"}],"params":[{"doc":"The text.","name":"text","required":true,"type":"text"},{"default":"${local://theme#accent_surface}","doc":"Fill colour.","name":"background","type":"text"},{"default":"${local://theme#accent}","doc":"Text colour.","name":"color","type":"text"},{"default":"Caption","doc":"A core://Text style.","name":"style","type":"text"},{"default":8,"doc":"Corner radius.","name":"corner","type":"number"}],"template":{"background":"$arg.background","content":{"style":"$arg.style","type":"core://Text","value_expr":"$arg.text"},"content_color":"$arg.color","corner_dp":"$arg.corner","padding_h_dp":8,"padding_v_dp":3,"type":"core://Box"}}','A corner parameter (default 8, as before), so tighter tags are pills too','server','0ea916336c7a47161c7b3029e50faacee83bf6bee35b4a0698f58621789678a7',NULL,1794840857);
INSERT INTO components VALUES('core:pixelfed_comment_box',1,'{"doc":"A box that comments on the post of the screen''s route ($route.id): the comment shows at once as Sending… and the screen reloads.","examples":[{"args":{},"note":"The footer of a post screen"}],"params":[],"template":{"field":"comment","max_length":500,"on_submit":{"endpoint":"/v1/pixelfed/posts/comment","entity":{"author_name":"You","depth":0,"meta":"Sending…","text":"$form.comment"},"entity_uri":"pixelfed://comments/pending-$nonce","intent":"action.mutation.create","payload":{"client_id":"$nonce","id":"$route.id","text":"$form.comment"},"query_key":"comments:$route.id","refresh_workspace":true},"placeholder":"Add a comment…","type":"core://TextField"}}','First version: the Pixelfed blueprint''s comment box, the footer of its post screens (issue #128)','server','5851310e5fcaebbf44ed10db488fa68504aad32fe9c58b98645f012dfdd37806',NULL,1794840857);
INSERT INTO components VALUES('core:pixelfed_post',1,'{"doc":"A Pixelfed post on its own screen: the post (author, photos, caption, like and boost) and its comments, in a screen whose route has the post''s id ($route.id). With focus, that comment is scrolled to and highlighted. Goes in a screen''s content, with core:pixelfed_comment_box as its footer.","examples":[{"args":{},"note":"A post and its comments"},{"args":{"focus":"pixelfed://comments/$route.comment"},"note":"Opened on one comment of the thread"}],"params":[{"default":"","doc":"The comment to scroll to and highlight, e.g. pixelfed://comments/$route.comment; empty for none.","name":"focus","type":"text"}],"template":{"children":[{"empty_text":"Post not found","item_template":{"children":[{"content":{"icon":"repeat","text":"$item.reblogged_by_name boosted","type":"core://Badge"},"type":"core://Conditional","value":"$item.reblogged_by_name"},{"args":{"avatar":"$item.author_avatar_url","handle":"$item.author_handle","name":"$item.author_name"},"component":"core:author_header","type":"core://Use"},{"aspect_field":"aspect_ratio","aspect_ratio":1.0,"item_template":{"blurhash":"$item.blurhash","content_description":"$item.alt_text","type":"core://Image","url":"$item.url"},"items":"$item.media_uris","tag":"carousel:$item.uri","type":"core://Carousel"},{"children":[{"args":{"active_icon":"favorite","active_label":"Unlike","count_field":"like_count","endpoint":"/v1/pixelfed/posts/like","field":"is_liked","icon":"favorite_border","label":"Like","payload_field":"liked","tag":"like:$item.uri","tint":"#ED4956"},"component":"core:toggle_action","type":"core://Use"},{"style":"Label","type":"core://Text","value_expr":"$item.like_count"},{"type":"core://Spacer"},{"args":{"active_icon":"bookmark","active_label":"Remove bookmark","endpoint":"/v1/pixelfed/posts/bookmark","field":"is_bookmarked","icon":"bookmark_border","label":"Bookmark","payload_field":"bookmarked","tag":"bookmark:$item.uri"},"component":"core:toggle_action","type":"core://Use"}],"padding_h_dp":4,"type":"core://Row"},{"content":{"children":[{"args":{"text":"$item.content_warning_label"},"component":"core:warning_chip","type":"core://Use"}],"padding_h_dp":14,"padding_v_dp":4,"type":"core://Column"},"type":"core://Conditional","value":"$item.content_warning"},{"content":{"children":[{"style":"Body","type":"core://Text","value_expr":"$item.caption"}],"padding_h_dp":14,"type":"core://Column"},"type":"core://Conditional","value":"$item.caption"},{"size_dp":12,"type":"core://Spacer"},{"type":"core://Divider"},{"children":[{"style":"Label","type":"core://Text","value_expr":"Comments"}],"padding_h_dp":14,"padding_v_dp":8,"type":"core://Row"}],"type":"core://Column"},"query_key":"post:$route.id","type":"core://List"},{"empty_text":"No comments yet. Be the first!","focus":{"arg":"focus","then":{"background":"#FFF3CF","uri":"$arg.focus"},"type":"core://IfArg"},"indent":{"field":"depth","max":4,"step_dp":20},"item_template":{"children":[{"children":[{"content_description":"$item.author_name","shape":"Circle","size_dp":24,"type":"core://Image","url":"$item.avatar_url"},{"style":"Label","type":"core://Text","value_expr":"$item.author_name"}],"spacing_dp":8,"type":"core://Row"},{"style":"Body","type":"core://Text","value_expr":"$item.text"},{"children":[{"style":"Secondary","type":"core://Text","value_expr":"$item.meta"},{"type":"core://Spacer"},{"content":{"style":"Secondary","type":"core://Text","value_expr":"$item.like_count"},"type":"core://Conditional","value":"$item.like_count"},{"content":{"active":"$item.is_liked","active_content_description":"Unlike comment by $item.author_name","active_icon":"favorite","active_tint":"#ED4956","content_description":"Like comment by $item.author_name","icon":"favorite_border","on_click":{"also":[{"field":"like_count","value_expr":"entity.is_liked ? entity.like_count - 1 : entity.like_count + 1"}],"endpoint":"/v1/pixelfed/posts/like","entity_uri":"$item.uri","field":"is_liked","intent":"action.mutation.optimistic","payload":{"id":"$item.id","liked":"$value"},"rollback_value":false,"value_expr":"!entity.is_liked"},"size_dp":18,"tag":"like:$item.uri","type":"core://IconButton"},"type":"core://Conditional","value":"$item.id"}],"spacing_dp":0,"type":"core://Row"}],"padding_h_dp":12,"padding_v_dp":4,"spacing_dp":0,"type":"core://Column"},"query_key":"comments:$route.id","type":"core://List"}],"type":"core://Column"}}','First version: the Pixelfed blueprint''s post screen content, shared by its post, comments and comment_thread screens (issue #128)','server','29ae7f13a9bbd90daf3fe6563b890817bbc4831609bb0c0c4032c8cfca29e4be',NULL,1794840857);
INSERT INTO components VALUES('core:pixelfed_post',2,'{"doc":"A Pixelfed post on its own screen: the post (author, photos, caption, like and boost) and its comments, in a screen whose route has the post''s id ($route.id). With focus, that comment is scrolled to and highlighted. Goes in a screen''s content, with core:pixelfed_comment_box as its footer.","examples":[{"args":{},"note":"A post and its comments"},{"args":{"focus":"pixelfed://comments/$route.comment"},"note":"Opened on one comment of the thread"}],"params":[{"default":"","doc":"The comment to scroll to and highlight, e.g. pixelfed://comments/$route.comment; empty for none.","name":"focus","type":"text"}],"template":{"children":[{"empty_text":"Post not found","item_template":{"children":[{"content":{"icon":"repeat","text":"$item.reblogged_by_name boosted","type":"core://Badge"},"type":"core://Conditional","value":"$item.reblogged_by_name"},{"args":{"avatar":"$item.author_avatar_url","handle":"$item.author_handle","name":"$item.author_name"},"component":"core:author_header","type":"core://Use"},{"aspect_field":"aspect_ratio","aspect_ratio":1.0,"item_template":{"blurhash":"$item.blurhash","content_description":"$item.alt_text","type":"core://Image","url":"$item.url"},"items":"$item.media_uris","tag":"carousel:$item.uri","type":"core://Carousel"},{"children":[{"args":{"active_icon":"favorite","active_label":"Unlike","count_field":"like_count","endpoint":"/v1/pixelfed/posts/like","field":"is_liked","icon":"favorite_border","label":"Like","payload_field":"liked","tag":"like:$item.uri","tint":"#ED4956"},"component":"core:toggle_action","type":"core://Use"},{"style":"Label","type":"core://Text","value_expr":"$item.like_count"},{"type":"core://Spacer"},{"args":{"active_icon":"bookmark","active_label":"Remove bookmark","endpoint":"/v1/pixelfed/posts/bookmark","field":"is_bookmarked","icon":"bookmark_border","label":"Bookmark","payload_field":"bookmarked","tag":"bookmark:$item.uri"},"component":"core:toggle_action","type":"core://Use"}],"padding_h_dp":4,"type":"core://Row"},{"content":{"children":[{"args":{"text":"$item.content_warning_label"},"component":"core:warning_chip","type":"core://Use"}],"padding_h_dp":14,"padding_v_dp":4,"type":"core://Column"},"type":"core://Conditional","value":"$item.content_warning"},{"content":{"children":[{"style":"Body","type":"core://Text","value_expr":"$item.caption"}],"padding_h_dp":14,"type":"core://Column"},"type":"core://Conditional","value":"$item.caption"},{"size_dp":12,"type":"core://Spacer"},{"type":"core://Divider"},{"children":[{"style":"Label","type":"core://Text","value_expr":"Comments"}],"padding_h_dp":14,"padding_v_dp":8,"type":"core://Row"}],"type":"core://Column"},"query_key":"post:$route.id","type":"core://List"},{"empty_text":"No comments yet. Be the first!","focus":{"arg":"focus","then":{"background":"${local://theme#highlight}","uri":"$arg.focus"},"type":"core://IfArg"},"indent":{"field":"depth","max":4,"step_dp":20},"item_template":{"children":[{"children":[{"content_description":"$item.author_name","shape":"Circle","size_dp":24,"type":"core://Image","url":"$item.avatar_url"},{"style":"Label","type":"core://Text","value_expr":"$item.author_name"}],"spacing_dp":8,"type":"core://Row"},{"style":"Body","type":"core://Text","value_expr":"$item.text"},{"children":[{"style":"Secondary","type":"core://Text","value_expr":"$item.meta"},{"type":"core://Spacer"},{"content":{"style":"Secondary","type":"core://Text","value_expr":"$item.like_count"},"type":"core://Conditional","value":"$item.like_count"},{"content":{"active":"$item.is_liked","active_content_description":"Unlike comment by $item.author_name","active_icon":"favorite","active_tint":"#ED4956","content_description":"Like comment by $item.author_name","icon":"favorite_border","on_click":{"also":[{"field":"like_count","value_expr":"entity.is_liked ? entity.like_count - 1 : entity.like_count + 1"}],"endpoint":"/v1/pixelfed/posts/like","entity_uri":"$item.uri","field":"is_liked","intent":"action.mutation.optimistic","payload":{"id":"$item.id","liked":"$value"},"rollback_value":false,"value_expr":"!entity.is_liked"},"size_dp":18,"tag":"like:$item.uri","type":"core://IconButton"},"type":"core://Conditional","value":"$item.id"}],"spacing_dp":0,"type":"core://Row"}],"padding_h_dp":12,"padding_v_dp":4,"spacing_dp":0,"type":"core://Column"},"query_key":"comments:$route.id","type":"core://List"}],"type":"core://Column"}}','Theme colours: the highlight token for a focused comment, so it follows dark mode','server','e93a7a4f29183c4033c2f32c8cfc3e0a347ac8cb37bb0ea2c6ebc9afa8afbe8a',NULL,1794840857);
INSERT INTO components VALUES('core:pixelfed_sign_in',1,'{"doc":"Pixelfed''s sign-in: a sentence naming the server, a ''Sign in with Pixelfed'' button for it, and, when other servers are allowed, a server box with its own button. The pod serves it as the Pixelfed blueprint''s signed-out screen; a layout can use it too (the buttons start the pod''s Pixelfed sign-in, action.auth.login).","examples":[{"args":{"instance_url":"https://pixelfed.social","server":"pixelfed.social"},"note":"One server: the sentence and its button."},{"args":{"instance_url":"https://pixelfed.social","other_servers":true,"placeholder":"Server, e.g. pixelfed.example","server":"pixelfed.social"},"note":"Other servers allowed: the server box and its button too."}],"params":[{"doc":"The server the sentence names, e.g. pixelfed.social.","name":"server","required":true,"type":"text"},{"doc":"The server ''Sign in with Pixelfed'' signs in to, e.g. https://pixelfed.social.","name":"instance_url","required":true,"type":"uri"},{"default":false,"doc":"Offer a box to sign in to another server (local:providers#custom_server says whether the pod allows it).","name":"other_servers","type":"bool"},{"default":"Server, e.g. pixelfed.social","doc":"The server box''s placeholder.","name":"placeholder","type":"text"}],"template":{"children":[{"style":"Body","type":"core://Text","value_expr":"Sign in to $arg.server to see your home feed. Your Pixelfed token stays on your pod."},{"label":"Sign in with Pixelfed","on_click":{"app_path":"/v1/auth/pixelfed/app","instance_url":"$arg.instance_url","intent":"action.auth.login","token_path":"/v1/auth/pixelfed/token"},"type":"core://Button"},{"arg":"other_servers","then":{"children":[{"style":"Body","type":"core://Text","value_expr":"Or sign in to another Pixelfed server:"},{"field":"instance","max_length":253,"placeholder":"$arg.placeholder","type":"core://TextField"},{"label":"Sign in to this server","on_click":{"app_path":"/v1/auth/pixelfed/app","instance_url":"$form.instance","intent":"action.auth.login","token_path":"/v1/auth/pixelfed/token"},"type":"core://Button"}],"type":"core://Fragment"},"type":"core://IfArg"}],"orientation":"Vertical","padding_dp":16,"type":"core://Container"}}','First version: the signed-out screen the Pixelfed adapter built in code','server','1b45b424999fcfeab5402a2a35503fba5f5080235d720efb5a8582c591228e3f',NULL,1794840857);
INSERT INTO components VALUES('core:screen',1,'{"children":true,"doc":"A screen the way a workspace screen looks: a bar with Back, the title and a spinner while its data loads, the load''s error with Try again, the content (scrolling, following its end after an action) and an optional footer below a divider. Children: the content, then the footer.","examples":[{"args":{"data":"/v1/example/post","title":"Post"},"children":[{"style":"Body","type":"core://Text","value_expr":"A post"}],"note":"a screen with data"},{"args":{"has_footer":true,"title":"Comments"},"children":[{"style":"Body","type":"core://Text","value_expr":"Comments"},{"field":"c","placeholder":"Add a comment","type":"core://TextField"}],"note":"with a footer"}],"params":[{"doc":"The screen''s title (bindings allowed).","name":"title","required":true,"type":"text"},{"default":"","doc":"The screen''s data path (for Try again).","name":"data","type":"text"},{"default":false,"doc":"The second child is a footer.","name":"has_footer","type":"bool"}],"template":{"children":[{"children":[{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"screen-back","type":"core://IconButton"},{"style":"Title","type":"core://Text","value_expr":"$arg.title"},{"content":{"size_dp":16,"type":"core://Progress"},"type":"core://Conditional","value":"${local://screen#loading}"},{"size_dp":12,"type":"core://Spacer"}],"padding_v_dp":4,"spacing_dp":0,"type":"core://Row"},{"type":"core://Divider"},{"arg":"data","then":{"content":{"children":[{"content":{"style":"Caption","type":"core://Text","value_expr":"${local://screen#error}"},"content_color":"#B3261E","type":"core://Box"},{"type":"core://Spacer"},{"label":"Try again","on_click":{"intent":"action.data.load","path":"$arg.data"},"type":"core://Button"}],"padding_h_dp":16,"padding_v_dp":4,"spacing_dp":8,"type":"core://Row"},"type":"core://Conditional","value":"${local://screen#error}"},"type":"core://IfArg"},{"content":{"at":0,"type":"core://Children"},"follow_end":true,"type":"core://Scroll"},{"arg":"has_footer","then":{"children":[{"type":"core://Divider"},{"children":[{"at":1,"type":"core://Children"}],"padding_h_dp":12,"padding_v_dp":8,"type":"core://Column"}],"type":"core://Fragment"},"type":"core://IfArg"}],"type":"core://Column"}}','First version','server','e9e32433babe31aa2c306f5ed3218722a2d7963271402c15661d9f63d9d6cb93',NULL,1794840857);
INSERT INTO components VALUES('core:screen',2,'{"children":true,"doc":"A screen the way a workspace screen looks: a bar with Back, the title and a spinner while its data loads, the load''s error with Try again, the content (scrolling, following its end after an action) and an optional footer below a divider. Children: the content, then the footer.","examples":[{"args":{"data":"/v1/example/post","title":"Post"},"children":[{"style":"Body","type":"core://Text","value_expr":"A post"}],"note":"a screen with data"},{"args":{"has_footer":true,"title":"Comments"},"children":[{"style":"Body","type":"core://Text","value_expr":"Comments"},{"field":"c","placeholder":"Add a comment","type":"core://TextField"}],"note":"with a footer"}],"params":[{"doc":"The screen''s title (bindings allowed).","name":"title","required":true,"type":"text"},{"default":"","doc":"The screen''s data path (for Try again).","name":"data","type":"text"},{"default":false,"doc":"The second child is a footer.","name":"has_footer","type":"bool"}],"template":{"children":[{"children":[{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"screen-back","type":"core://IconButton"},{"style":"Title","type":"core://Text","value_expr":"$arg.title"},{"content":{"size_dp":16,"type":"core://Progress"},"type":"core://Conditional","value":"${local://screen#loading}"},{"size_dp":12,"type":"core://Spacer"}],"padding_v_dp":4,"spacing_dp":0,"type":"core://Row"},{"type":"core://Divider"},{"arg":"data","then":{"content":{"children":[{"content":{"style":"Caption","type":"core://Text","value_expr":"${local://screen#error}"},"content_color":"${local://theme#error}","type":"core://Box"},{"type":"core://Spacer"},{"label":"Try again","on_click":{"intent":"action.data.load","path":"$arg.data"},"type":"core://Button"}],"padding_h_dp":16,"padding_v_dp":4,"spacing_dp":8,"type":"core://Row"},"type":"core://Conditional","value":"${local://screen#error}"},"type":"core://IfArg"},{"content":{"at":0,"type":"core://Children"},"follow_end":true,"type":"core://Scroll"},{"arg":"has_footer","then":{"children":[{"type":"core://Divider"},{"children":[{"at":1,"type":"core://Children"}],"padding_h_dp":12,"padding_v_dp":8,"type":"core://Column"}],"type":"core://Fragment"},"type":"core://IfArg"}],"type":"core://Column"}}','Theme colours: the error token for a load error, so it follows dark mode','server','0f3046d6be9d21519b04dac0c52a71ca51b77eb4d458a62f3aee5d57c2b7d9b7',NULL,1794840857);
INSERT INTO components VALUES('core:scroll_page',1,'{"children":true,"doc":"A whole page with its own header: on the page colour, core:page_header (Back while the page can go back, and the title), a divider, then its children in a column that scrolls. The root of a core://Page or of one of its screens.","examples":[{"args":{"title":"Reading list"},"children":[{"size_dp":12,"type":"core://Spacer"},{"args":{"text":"This month"},"component":"core:section_header","type":"core://Use"},{"style":"Body","type":"core://Text","value_expr":"The Lighthouse Keeper"},{"size_dp":24,"type":"core://Spacer"}],"note":"a list page, its children spaced by themselves"},{"args":{"padding_h":16,"padding_v":16,"spacing":12,"title":"$item.title"},"children":[{"style":"Body","type":"core://Text","value_expr":"$item.notes"},{"args":{"label":"Open","url":"$item.url"},"component":"core:link_button","type":"core://Use"}],"note":"an item''s screen, padded and spaced"}],"params":[{"doc":"The title (bindings allowed).","name":"title","required":true,"type":"text"},{"default":0,"doc":"Space between the children; 0 for none.","name":"spacing","type":"number"},{"default":0,"doc":"Side padding of the scrolling column; 0 for none.","name":"padding_h","type":"number"},{"default":0,"doc":"Top and bottom padding of the scrolling column; 0 for none.","name":"padding_v","type":"number"}],"template":{"background":"${local://theme#page}","content":{"children":[{"args":{"title":"$arg.title"},"component":"core:page_header","type":"core://Use"},{"type":"core://Divider"},{"content":{"children":[{"type":"core://Children"}],"padding_h_dp":{"arg":"padding_h","then":"$arg.padding_h","type":"core://IfArg"},"padding_v_dp":{"arg":"padding_v","then":"$arg.padding_v","type":"core://IfArg"},"spacing_dp":{"arg":"spacing","then":"$arg.spacing","type":"core://IfArg"},"type":"core://Column"},"type":"core://Scroll"}],"type":"core://Column"},"fill":true,"type":"core://Box"}}','First version: the page with its own header and a scrolling column (on the page colour, under a divider) that page layouts repeat','server','aad7cea85ec755832f5beb2edb5715fe653db22d462707a1049f19086d066b90',NULL,1794840857);
INSERT INTO components VALUES('core:section_header',1,'{"doc":"A section''s heading: padded text, optionally under a divider (settings groups, ''Alerts'', ''Events'').","examples":[{"args":{"divider":true,"text":"Sign-ins"},"note":"a settings group"},{"args":{"padding_v":4,"style":"Title","text":"Alerts"},"note":"a screen section"}],"params":[{"doc":"The heading (bindings allowed).","name":"text","required":true,"type":"text"},{"default":"Label","doc":"A core://Text style.","name":"style","type":"text"},{"default":8,"doc":"Space above and below.","name":"padding_v","type":"number"},{"default":false,"doc":"Draw a divider above it.","name":"divider","type":"bool"}],"template":{"arg":"divider","else":{"children":[{"style":"$arg.style","type":"core://Text","value_expr":"$arg.text"}],"padding_h_dp":16,"padding_v_dp":"$arg.padding_v","type":"core://Column"},"then":{"children":[{"type":"core://Divider"},{"children":[{"style":"$arg.style","type":"core://Text","value_expr":"$arg.text"}],"padding_h_dp":16,"padding_v_dp":"$arg.padding_v","type":"core://Column"}],"type":"core://Fragment"},"type":"core://IfArg"}}','First version','server','7cb4fa94659544e8a95f9f42a32b54ae82b489f119e479074538f6b720005d33',NULL,1794840857);
INSERT INTO components VALUES('core:stat',1,'{"doc":"A number with a label under it (a count tile).","examples":[{"args":{"label":"recipes","value":"$item.count"},"note":"a count"}],"params":[{"doc":"The number (bindings allowed).","name":"value","required":true,"type":"text"},{"doc":"What it counts.","name":"label","required":true,"type":"text"}],"template":{"align":"Center","children":[{"style":"Display","type":"core://Text","value_expr":"$arg.value"},{"style":"Secondary","type":"core://Text","value_expr":"$arg.label"}],"spacing_dp":2,"type":"core://Column"}}','First version','server','1b5fdbf635c2d74d3963d3a8a80016f16cebfc5c6011925acc59a7d7626899d2',NULL,1794840857);
INSERT INTO components VALUES('core:toggle_action',1,'{"doc":"An icon button that flips a boolean field of the item at once and tells an action endpoint ({id, <payload_field>: the new value}); optionally keeps a count field in step (a like with its count).","examples":[{"args":{"active_icon":"favorite","active_label":"Unlike","count_field":"like_count","endpoint":"/v1/pixelfed/posts/like","field":"is_liked","icon":"favorite_border","label":"Like","payload_field":"liked","tint":"#ED4956"},"note":"a like with its count"}],"params":[{"doc":"The item''s boolean field (is_liked).","name":"field","required":true,"type":"text"},{"doc":"Icon while off.","name":"icon","required":true,"type":"text"},{"doc":"Icon while on.","name":"active_icon","required":true,"type":"text"},{"doc":"What it does while off (Like).","name":"label","required":true,"type":"text"},{"doc":"What it does while on (Unlike).","name":"active_label","required":true,"type":"text"},{"doc":"The action endpoint.","name":"endpoint","required":true,"type":"text"},{"doc":"The payload''s field for the new value.","name":"payload_field","required":true,"type":"text"},{"default":"","doc":"Icon colour while on (#RRGGBB).","name":"tint","type":"text"},{"default":"","doc":"A count field to move by one with it.","name":"count_field","type":"text"},{"default":"","doc":"A test tag (bindable).","name":"tag","type":"text"}],"template":{"active":"$item.$arg.field","active_content_description":"$arg.active_label","active_icon":"$arg.active_icon","active_tint":{"arg":"tint","then":"$arg.tint","type":"core://IfArg"},"content_description":"$arg.label","icon":"$arg.icon","on_click":{"also":{"arg":"count_field","then":[{"field":"$arg.count_field","value_expr":"entity.$arg.field ? entity.$arg.count_field - 1 : entity.$arg.count_field + 1"}],"type":"core://IfArg"},"endpoint":"$arg.endpoint","entity_uri":"$item.uri","field":"$arg.field","intent":"action.mutation.optimistic","payload":{"$arg.payload_field":"$value","id":"$item.id"},"rollback_value":false,"value_expr":"!entity.$arg.field"},"tag":{"arg":"tag","then":"$arg.tag","type":"core://IfArg"},"type":"core://IconButton"}}','First version','server','becc2e7cffa558b3d136d9874e6f17f7f5f98e081bcb9f7f2b0d624302514c0d',NULL,1794840857);
INSERT INTO components VALUES('core:warning_chip',1,'{"doc":"A warning chip: a warning icon and text in the warning tone.","examples":[{"args":{"text":"Needs attention"},"note":"a failing source"}],"params":[{"doc":"The warning.","name":"text","required":true,"type":"text"}],"template":{"icon":"warning","text":"$arg.text","tone":"Warning","type":"core://Chip"}}','First version','server','964e498963b8c0674d94bd94aaea99da5994c8972215f9bc840d2e0fed874d64',NULL,1794840857);
INSERT INTO components VALUES('core:workspace',1,'{"children":true,"doc":"A page the way a core://Workspace looks: the title in the headline style (with Back when the page was pushed) pinned above its content, which scrolls, then a little space. With title_scrolls the title scrolls away with the content; with fills_screen the one child fills the page and there is no title. Drawn inline in another layout, only the content shows. Copy it to make your own page chrome.","examples":[{"args":{"title":"Recipes"},"children":[{"style":"Body","type":"core://Text","value_expr":"Soup"}],"note":"a pinned title"},{"args":{"title":"Feed","title_scrolls":true},"children":[{"style":"Body","type":"core://Text","value_expr":"Post"}],"note":"a title that scrolls away"}],"params":[{"doc":"The page title.","name":"title","required":true,"type":"text"},{"default":false,"doc":"The title scrolls with the content.","name":"title_scrolls","type":"bool"},{"default":false,"doc":"The one child fills the page: no title, no scrolling.","name":"fills_screen","type":"bool"}],"template":{"arg":"fills_screen","else":{"arg":"title_scrolls","else":{"children":[{"content":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"children":[{"style":"Headline","type":"core://Text","value_expr":"$arg.title"}],"padding_h_dp":16,"padding_v_dp":12,"type":"core://Column"}],"type":"core://Row"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"},{"content":{"children":[{"type":"core://Children"},{"content":{"size_dp":16,"type":"core://Spacer"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"}],"type":"core://Column"},"type":"core://Scroll"}],"type":"core://Column"},"then":{"content":{"children":[{"content":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"children":[{"style":"Headline","type":"core://Text","value_expr":"$arg.title"}],"padding_h_dp":16,"padding_v_dp":12,"type":"core://Column"}],"type":"core://Row"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"},{"type":"core://Children"},{"content":{"size_dp":16,"type":"core://Spacer"},"equals":"false","type":"core://Conditional","value":"${local://nav#inline}"}],"type":"core://Column"},"type":"core://Scroll"},"type":"core://IfArg"},"then":{"children":[{"content":{"content_description":"Back","icon":"arrow_back","on_click":{"intent":"action.navigation.back"},"tag":"layout-back","type":"core://IconButton"},"type":"core://Conditional","value":"${local://nav#pushed}"},{"at":0,"type":"core://Children"}],"type":"core://Column"},"type":"core://IfArg"}}','First version','server','0f54c7959502ce60e3317f29b425f0a96ee83e9d63cf76eb6d71a7768f74cfa2',NULL,1794840857);
INSERT INTO components VALUES('pod:tile',1,'{"children":true,"doc":"A tile that opens something.","examples":[{"args":{"label":"Dinner"},"note":"A tile"}],"params":[{"doc":"What it says","name":"label","required":true,"type":"text"}],"template":{"background":"${local://theme#card}","content":{"children":[{"style":"Title","type":"core://Text","value_expr":"$arg.label"},{"type":"core://Children"}],"spacing_dp":4,"type":"core://Column"},"corner_dp":14,"padding_h_dp":12,"padding_v_dp":10,"type":"core://Box"}}','Defined','claude',NULL,NULL,1794840858);
INSERT INTO components VALUES('pod:tile',2,'{"children":true,"doc":"A tile that opens something.","examples":[{"args":{"label":"Dinner"},"note":"A tile"}],"params":[{"doc":"What it says","name":"label","required":true,"type":"text"}],"template":{"background":"${local://theme#card}","content":{"children":[{"style":"Title","type":"core://Text","value_expr":"› $arg.label"},{"type":"core://Children"}],"spacing_dp":4,"type":"core://Column"},"corner_dp":14,"padding_h_dp":12,"padding_v_dp":10,"type":"core://Box"}}','Edited','claude',NULL,NULL,1794840858);
CREATE TABLE jacks (
            id         TEXT PRIMARY KEY NOT NULL,
            plugged    INTEGER NOT NULL,
            config     TEXT NOT NULL DEFAULT '{}',
            secrets    TEXT NOT NULL DEFAULT '{}',
            updated_at INTEGER NOT NULL
        );
CREATE TABLE agent_usage (
            day     TEXT NOT NULL,
            feature TEXT NOT NULL,
            calls   INTEGER NOT NULL,
            PRIMARY KEY (day, feature)
        ) WITHOUT ROWID;
CREATE TABLE mcp_servers (
            name       TEXT PRIMARY KEY NOT NULL,
            url        TEXT NOT NULL,
            auth       TEXT NOT NULL,
            config     TEXT NOT NULL DEFAULT '{}',
            secrets    TEXT NOT NULL DEFAULT '{}',
            state      TEXT NOT NULL,
            last_error TEXT,
            tools      TEXT NOT NULL DEFAULT '[]',
            created_at INTEGER NOT NULL,
            updated_at INTEGER NOT NULL
        );
CREATE TABLE pixelfed_session_instance (
             token_hash TEXT PRIMARY KEY NOT NULL,
             instance   TEXT NOT NULL
         );
CREATE TABLE pixelfed_pending_posts (
     token_hash TEXT NOT NULL,
     client_id  TEXT NOT NULL,
     caption    TEXT NOT NULL,
     upload_ids TEXT NOT NULL,
     media_ids  TEXT NOT NULL DEFAULT '[]',
     state      TEXT NOT NULL,
     error      TEXT,
     status_id  TEXT,
     attempts   INTEGER NOT NULL DEFAULT 0,
     created_at INTEGER NOT NULL,
