CREATE TABLE collections_defs (
    name       TEXT NOT NULL,
    version    INTEGER NOT NULL,
    def_json   TEXT NOT NULL,
    note       TEXT NOT NULL,
    author     TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    PRIMARY KEY (name, version)
);
INSERT INTO collections_defs VALUES('events',1,'{"name":"events","title":"Events","fields":[{"id":"f1","name":"source_id","type":"text","optional":true},{"id":"f2","name":"title","type":"text","optional":true},{"id":"f3","name":"start","type":"datetime","optional":true},{"id":"f4","name":"end","type":"datetime","optional":true},{"id":"f5","name":"venue","type":"text","optional":true},{"id":"f6","name":"description","type":"text","optional":true},{"id":"f7","name":"url","type":"text","optional":true},{"id":"f8","name":"tickets_url","type":"text","optional":true},{"id":"f9","name":"seen","type":"bool","optional":false,"default":false}],"order_by":"f3","next_field":10,"system":{"app":"events","channel":"matches","alert_title":"{title}","alert_body":"{start_text} · {venue} — {alert}"}}','The Events app''s events','pod',1794840858);
CREATE TABLE collections_rows (
    collection  TEXT NOT NULL,
    id          TEXT NOT NULL,
    client_id   TEXT,
    values_json TEXT NOT NULL,
    created_at  INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL,
    deleted_at  INTEGER, filler TEXT,
    PRIMARY KEY (collection, id)
);
CREATE TABLE collections_aside (
    collection  TEXT NOT NULL,
    row_id      TEXT NOT NULL,
    field_id    TEXT NOT NULL,
    value_json  TEXT NOT NULL,
    def_version INTEGER NOT NULL,
    created_at  INTEGER NOT NULL,
    PRIMARY KEY (collection, row_id, field_id)
);
CREATE TABLE collections_edits (
    id         TEXT PRIMARY KEY NOT NULL,
    collection TEXT NOT NULL,
    note       TEXT NOT NULL,
    count      INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    undone_at  INTEGER
, client_id TEXT);
CREATE TABLE collections_edit_rows (
    edit_id     TEXT NOT NULL,
    row_id      TEXT NOT NULL,
    before_json TEXT,
    after_json  TEXT NOT NULL, collection TEXT,
    PRIMARY KEY (edit_id, row_id)
);
CREATE TABLE collections_computed (
    collection TEXT NOT NULL,
    field_id   TEXT NOT NULL,
    key        TEXT NOT NULL,
    value      TEXT NOT NULL,
    source     TEXT NOT NULL,
    updated_at INTEGER NOT NULL,
    PRIMARY KEY (collection, field_id, key)
);
CREATE TABLE collections_reminders_sent (
    collection TEXT NOT NULL,
    reminder   TEXT NOT NULL,
    row_id     TEXT NOT NULL,
    date       TEXT NOT NULL,
    sent_at    INTEGER NOT NULL,
    PRIMARY KEY (collection, reminder, row_id, date)
);
CREATE TABLE collections_fills (
    collection   TEXT NOT NULL,
    filler       TEXT NOT NULL,
    fingerprint  TEXT NOT NULL DEFAULT '',
    next_at      INTEGER,
    etag         TEXT,
    last_modified TEXT,
    content_hash TEXT,
    last_fill_at INTEGER,
    last_ok_at   INTEGER,
    last_error   TEXT,
    failures     INTEGER NOT NULL DEFAULT 0,
    empty_runs   INTEGER NOT NULL DEFAULT 0,
    last_rows    INTEGER,
    last_skipped INTEGER,
    day          TEXT,
    day_fills    INTEGER NOT NULL DEFAULT 0,
    quiet_next   INTEGER NOT NULL DEFAULT 0, last_past INTEGER,
    PRIMARY KEY (collection, filler)
);
CREATE TABLE collections_alerts_sent (
    collection TEXT NOT NULL,
    alert      TEXT NOT NULL,
    row_id     TEXT NOT NULL,
    sent_at    INTEGER NOT NULL,
    PRIMARY KEY (collection, alert, row_id)
);
CREATE TABLE collections_secrets (
    name       TEXT PRIMARY KEY NOT NULL,
    value      TEXT NOT NULL,
    updated_at INTEGER NOT NULL
, host TEXT);
CREATE TABLE collections_deleted (
    name       TEXT PRIMARY KEY NOT NULL,
    deleted_at INTEGER NOT NULL
);
CREATE TABLE collections_row_fills (
    collection  TEXT NOT NULL,
    filler      TEXT NOT NULL,
    row_id      TEXT NOT NULL,
    source      TEXT NOT NULL,
    content_key TEXT NOT NULL,
    filled_at   INTEGER NOT NULL,
    PRIMARY KEY (collection, filler, row_id)
) WITHOUT ROWID;
CREATE TABLE collections_staged (
    token      TEXT PRIMARY KEY NOT NULL,
    collection TEXT NOT NULL,
    edits_json TEXT NOT NULL,
    note       TEXT NOT NULL,
    created_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TABLE collections_compute_failures (
    collection  TEXT NOT NULL,
    field_id    TEXT NOT NULL,
    key         TEXT NOT NULL,
    row_ids     TEXT NOT NULL,
    attempts    INTEGER NOT NULL,
    next_at     INTEGER NOT NULL,
    updated_at  INTEGER NOT NULL,
    PRIMARY KEY (collection, field_id, key)
) WITHOUT ROWID;
CREATE TABLE collections_field_writers (
    collection TEXT NOT NULL,
    row_id     TEXT NOT NULL,
    field_id   TEXT NOT NULL,
    writer     TEXT NOT NULL,
    at         INTEGER NOT NULL,
    PRIMARY KEY (collection, row_id, field_id)
) WITHOUT ROWID;
CREATE TABLE agents_runner (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    url TEXT NOT NULL,
    token TEXT NOT NULL,
    signed_in_at INTEGER NOT NULL
);
CREATE TABLE agents_state (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    state_json TEXT NOT NULL,
    connected INTEGER NOT NULL DEFAULT 0,
    last_error TEXT,
    last_ok_at INTEGER,
    updated_at INTEGER NOT NULL
, cursor INTEGER NOT NULL DEFAULT 0);
CREATE TABLE agents_launches (
    task_id TEXT PRIMARY KEY,
    collection TEXT NOT NULL,
    at INTEGER NOT NULL
, run_id TEXT NOT NULL DEFAULT '', request_id TEXT NOT NULL DEFAULT '');
CREATE TABLE agents_marks (
    key TEXT PRIMARY KEY,
    at INTEGER NOT NULL
);
CREATE TABLE agents_schedules (
    id              TEXT PRIMARY KEY NOT NULL,
    name            TEXT NOT NULL UNIQUE,
    cron            TEXT NOT NULL,
    timezone        TEXT NOT NULL,
    workspace       TEXT NOT NULL,
    model           TEXT NOT NULL DEFAULT '',
    max_runtime_min INTEGER NOT NULL,
    enabled         INTEGER NOT NULL DEFAULT 1,
    prompt          TEXT NOT NULL,
    looked_until    INTEGER NOT NULL,
    created_at      INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL
);
CREATE TABLE agents_occurrences (
    schedule_id TEXT NOT NULL,
    occurrence  TEXT NOT NULL,
    due_at      INTEGER NOT NULL,
    state       TEXT NOT NULL,
    request_id  TEXT NOT NULL,
    run_id      TEXT NOT NULL DEFAULT '',
    manual      INTEGER NOT NULL DEFAULT 0,
    updated_at  INTEGER NOT NULL,
    PRIMARY KEY (schedule_id, occurrence, manual)
) WITHOUT ROWID;
DELETE FROM sqlite_sequence;
CREATE INDEX layouts_by_workspace ON layouts (workspace_id);
CREATE INDEX uploads_owner ON uploads(owner);
CREATE INDEX notifications_unread ON notifications (read_at, layout);
CREATE INDEX recipes_by_category ON recipes(category);
CREATE INDEX recipes_ingredient_groups_by_recipe ON recipes_ingredient_groups(recipe_id);
CREATE INDEX recipes_ingredients_by_group ON recipes_ingredients(group_id);
CREATE INDEX recipes_instruction_groups_by_recipe ON recipes_instruction_groups(recipe_id);
CREATE INDEX recipes_steps_by_group ON recipes_steps(group_id);
CREATE UNIQUE INDEX collections_rows_client
    ON collections_rows (collection, client_id) WHERE client_id IS NOT NULL;
CREATE UNIQUE INDEX collections_edits_client
    ON collections_edits (client_id) WHERE client_id IS NOT NULL;
COMMIT;
